const notifications = $input.first().json;
const grouped = {};

// Group by email
for (const notif of notifications) {
  const email = notif.subscription.email;

  if (!grouped[email]) {
    grouped[email] = {
      email: email,
      bills: [],
      notification_ids: [],
      subscription: notif.subscription
    };
  }

  grouped[email].bills.push({
    id: notif.bill.id,
    title: notif.bill.title,
    ministry: notif.bill.ministry,
    status: notif.bill.status,
    date_introduced: notif.bill.date_introduced,
    matched_keywords: notif.matched_keywords,
    summary: notif.bill.summary
  });

  grouped[email].notification_ids.push(notif.id);
}

// Convert to array
return Object.values(grouped);

const data = $input.first().json;
const bills = data.bills;

let billsHtml = '';

for (const bill of bills) {
  const keywords = bill.matched_keywords.join(', ');
  const summaryPreview = bill.summary ? bill.summary.substring(0, 200) + '...' : 'No summary available';

  billsHtml += `
    <div class="bill-item">
      <h3 class="bill-title">${bill.title}</h3>
      <div class="bill-meta">
        <span class="badge badge-ministry">🏛️ ${bill.ministry}</span>
        <span class="badge badge-status">📊 ${bill.status}</span>
      </div>
      <div class="matched-keywords">
        <strong>⭐ Matched:</strong> ${keywords}
      </div>
      <p class="summary">${summaryPreview}</p>
      <a href="http://localhost:3000/bills/${bill.id}" class="read-more">Read Full Bill →</a>
      <hr style="margin: 20px 0; border: none; border-top: 1px solid #e0e0e0;">
    </div>
  `;
}

return [{
  json: {
    email: data.email,
    billsHtml: billsHtml,
    billCount: bills.length,
    notification_ids: data.notification_ids
  }
}];

